171	    /**
172	     * Rolls a registration date forward to a business day. When {@code date} falls on a Saturday or
173	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
174	     * to the effective registration date (whether supplied in the request or defaulted to the server
175	     * date) so that every stored {@code registrationDate}, and any value derived from it, lands on a
176	     * business day.
177	     *
178	     * @param date the effective registration date
179	     * @return the same date if it is a weekday, otherwise the following Monday
180	     */
181	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
182	        return switch (date.getDayOfWeek()) {
183	            case SATURDAY -> date.plusDays(2);
184	            case SUNDAY -> date.plusDays(1);
185	            default -> date;
186	        };
187	    }
188	
189	    /**
190	     * Counts the owners that already exist (before the current create) whose first and last names
191	     * both match the supplied names, compared case-insensitively. The returned value is captured on
192	     * the new owner at creation time and does not change as further owners are added later.
193	     *
194	     * @param firstName the new owner's first name
195	     * @param lastName  the new owner's last name
196	     * @return the number of pre-existing namesake owners
197	     */
198	    private int namesakeCount(String firstName, String lastName) {
199	        return (int) this.clinicService.findAllOwners().stream()
200	            .filter(existing -> existing.getFirstName() != null
201	                && existing.getFirstName().equalsIgnoreCase(firstName)
202	                && existing.getLastName() != null
203	                && existing.getLastName().equalsIgnoreCase(lastName))
204	            .count();
205	    }
206	
207	    /**
208	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where
209	     * {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3} is the
210	     * upper-cased first three letters of the last name, and {@code NNNN} is a per-city 4-digit
211	     * zero-padded sequence equal to one more than the number of owners already in that city
212	     * (e.g. {@code 'SYD-SMI-0007'}).
213	     *
214	     * @param city     the owner's city
215	     * @param lastName the owner's last name
216	     * @return the assigned customer code
217	     */
218	    private String nextCustomerCode(String city, String lastName) {
219	        String cityPrefix = first3Upper(city);
220	        String lastPrefix = first3Upper(lastName);
221	        String cityKey = normalizeForHousehold(city);
222	        long sequence = this.clinicService.findAllOwners().stream()
223	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
224	            .count() + 1L;
225	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
226	    }
227	
228	    /**
229	     * Returns the upper-cased first three characters of {@code value}, or fewer if the value is
230	     * shorter. A {@code null} value yields the empty string.
231	     *
232	     * @param value the source value
233	     * @return the upper-cased first three characters
234	     */
235	    private String first3Upper(String value) {
236	        String v = (value == null ? "" : value);
237	        return v.substring(0, Math.min(3, v.length())).toUpperCase(java.util.Locale.ROOT);
238	    }
239	
240	    /**
241	     * Normalizes a street address applied whenever an owner is created: leading and trailing
242	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
243	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
244	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
245	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
246	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
247	     * {@code '12 MAIN STREET'}.
248	     *
249	     * @param address the raw address as submitted, or {@code null} when absent
250	     * @return the normalized address, or the empty string when the value is blank
251	     */
252	    private String normalizeAddress(String address) {
253	        String collapsed = (address == null ? "" : address)
254	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
255	        if (collapsed.isEmpty()) {
256	            return "";
257	        }
258	        String[] tokens = collapsed.split(" ");
259	        for (int i = 0; i < tokens.length; i++) {
260	            switch (tokens[i]) {
261	                case "ST" -> tokens[i] = "STREET";
262	                case "RD" -> tokens[i] = "ROAD";
263	                case "AVE" -> tokens[i] = "AVENUE";
264	                default -> { }
265	            }
266	        }
267	        return String.join(" ", tokens);
268	    }
269	
270	    /**
271	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
272	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
273	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
274	     * empty string.
275	     *
276	     * @param value the raw value (last name or address) as submitted
277	     * @return the normalized comparison key
278	     */
279	    private String normalizeForHousehold(String value) {
280	        if (value == null) {
281	            return "";
282	        }
283	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
284	    }
285	
286	    /**
287	     * Derives the stable shared household identifier for a household, keyed on the normalized last
288	     * name and address. Because it is a pure function of those normalized keys, every owner in the
289	     * same household deterministically computes the same value. The identifier is the first 12
290	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
291	     * (the separator prevents distinct name/address pairs from colliding).
292	     *
293	     * @param lastNameKey the normalized last-name comparison key
294	     * @param addressKey  the normalized address comparison key
295	     * @return the stable household identifier
296	     */
297	    private String householdId(String lastNameKey, String addressKey) {
298	        String seed = lastNameKey + "�" + addressKey;
299	        try {
300	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
301	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
302	            StringBuilder sb = new StringBuilder(digest.length * 2);
303	            for (byte b : digest) {
304	                sb.append(String.format("%02x", b));
305	            }
306	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
307	        }
308	        catch (java.security.NoSuchAlgorithmException e) {
309	            throw new IllegalStateException("SHA-256 not available", e);
310	        }
311	    }
312	
313	    /**
314	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
315	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
316	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
317	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
318	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
319	     * is stored as {@code '+61412345678'}.
320	     *
321	     * @param telephone the raw telephone number as submitted
322	     * @return the normalized E.164 telephone number
323	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
324	     *         number (8 to 15 digits after the '+')
325	     */
326	    private String normalizeTelephone(String telephone) {
327	        String raw = telephone == null ? "" : telephone.trim();
328	        String digits = raw.replaceAll("\\D", "");
329	        String e164;
330	        if (raw.startsWith("+")) {
331	            e164 = "+" + digits;
332	        } else {
333	            if (digits.startsWith("0")) {
334	                digits = digits.substring(1);
335	            }
336	            e164 = "+61" + digits;
337	        }
338	        int digitCount = e164.length() - 1;
339	        if (digitCount < 8 || digitCount > 15) {
340	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
341	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
342	        }
343	        return e164;
344	    }
345	
346	    /**
347	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
348	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
349	     * (absent) or already valid.
350	     *
351	     * @param email the email address as submitted, or {@code null} when absent
352	     * @return the lower-cased email, or {@code null} when absent
353	     */
354	    private String normalizeEmail(String email) {
355	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
356	    }
