358	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
359	    @Override
360	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
361	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
362	        if (currentOwner == null) {
363	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
364	        }
365	        currentOwner.setAddress(ownerFieldsDto.getAddress());
366	        currentOwner.setCity(ownerFieldsDto.getCity());
367	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
368	        currentOwner.setLastName(ownerFieldsDto.getLastName());
369	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
370	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
371	        this.clinicService.saveOwner(currentOwner);
372	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
373	    }
