387	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
388	    @Override
389	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
390	        Owner owner = this.clinicService.findOwnerById(ownerId);
391	        if (owner == null) {
392	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
393	        }
394	        HttpHeaders headers = new HttpHeaders();
395	        Pet pet = petMapper.toPet(petFieldsDto);
396	        owner.setId(ownerId);
397	        pet.setOwner(owner);
398	        pet.getType().setName(null);
399	        this.clinicService.savePet(pet);
400	        PetDto petDto = petMapper.toPetDto(pet);
401	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
402	            .buildAndExpand(pet.getId()).toUri());
403	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
404	    }
