439	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
440	    @Override
441	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
442	        Owner owner = this.clinicService.findOwnerById(ownerId);
443	        if (owner != null) {
444	            Pet pet = owner.getPet(petId);
445	            if (pet != null) {
446	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
447	            }
448	        }
449	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
450	    }
